1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"sort"
10		"strings"
11		"syscall"
12	)
13	
14	// Manual review and false-positive analysis work strictly on top of
15	// archived evidence: submitting a review, querying revision history and
16	// re-evaluating a height range never need the original input files, never
17	// contact any network, never re-write a report, the enabled version or an
18	// alert record, and never trigger or revoke alerts.
19	
20	// Review statuses. A human marks an archived conclusion either as a real
21	// risk or as a false positive; submitting "unreviewed" withdraws earlier
22	// judgments of the same object without deleting the history.
23	const (
24		ReviewStatusReal          = "real"
25		ReviewStatusFalsePositive = "false_positive"
26		ReviewStatusUnreviewed    = "unreviewed"
27	)
28	
29	// Evaluation buckets for original conclusions carrying a valid review:
30	// real risks split into retained vs missed, false positives into still hit
31	// vs eliminated. Candidate hits without a valid review are pending.
32	const (
33		BucketRetained   = "retained"
34		BucketMissed     = "missed"
35		BucketStillHit   = "stillHit"
36		BucketEliminated = "eliminated"
37		BucketPending    = "pending"
38	)
39	
40	// ErrUnknownConclusion reports a review action targeting a conclusion that
41	// no archived report carries.
42	var ErrUnknownConclusion = errors.New("unknown conclusion")
43	
44	// ErrReviewConflict reports a submission whose expectedVersion is behind the
45	// object's current version.
46	var ErrReviewConflict = errors.New("review version conflict")
47	
48	// ErrSubmissionConflict reports a submission ID already stored with
49	// different field values. Submission IDs are unique archive-wide.
50	var ErrSubmissionConflict = errors.New("submission id already used with different content")
51	
52	// conclusionKey is the reviewed object's identity: chain, block hash,
53	// victim tx hash and conclusion kind. It deliberately excludes the alert
54	// channel, and blocks at the same height with different hashes are
55	// different objects.
56	type conclusionKey struct {
57		chainID   string
58		blockHash string
59		txHash    string
60		kind      string
61	}
62	
63	// ReviewRevision is one immutable submission. Revisions are append-only:
64	// rejudgments and withdrawals add a new revision while every earlier one is
65	// retained. ExpectedVersion records the optimistic-concurrency base the
66	// submitter believed in (0 for the first submission), keeping each
67	// revision's full submission content auditable.
68	type ReviewRevision struct {
69		Version         int    `json:"version"`
70		SubmissionID    string `json:"submissionId"`
71		Operator        string `json:"operator"`
72		Reason          string `json:"reason"`
73		Status          string `json:"status"`
74		ExpectedVersion int    `json:"expectedVersion"`
75	}
76	
77	// ReviewObject is the append-only revision stream for one conclusion
78	// identity. The current version is len(Revisions); the current status is
79	// the last revision's status (an "unreviewed" tail means withdrawn).
80	type ReviewObject struct {
81		ChainID   string           `json:"chainId"`
82		BlockHash string           `json:"blockHash"`
83		TxHash    string           `json:"txHash"`
84		Kind      string           `json:"kind"`
85		Revisions []ReviewRevision `json:"revisions"`
86	}
87	
88	func (o ReviewObject) key() conclusionKey {
89		return conclusionKey{o.ChainID, o.BlockHash, o.TxHash, o.Kind}
90	}
91	
92	// ReviewSubmission is one submitted review.
93	type ReviewSubmission struct {
94		ChainID         string
95		BlockHash       string
96		TxHash          string
97		Kind            string
98		SubmissionID    string
99		Operator        string
100		Reason          string
101		Status          string
102		ExpectedVersion int
103	}
104	
105	func (s ReviewSubmission) key() conclusionKey {
106		return conclusionKey{s.ChainID, s.BlockHash, s.TxHash, s.Kind}
107	}
108	
109	// contentEqual reports whether two submissions carry identical field
110	// values, including the target identity and the expected version.
111	func (s ReviewSubmission) contentEqual(o ReviewSubmission) bool {
112		return s == o
113	}
114	
115	func (s ReviewSubmission) revision(version int) ReviewRevision {
116		return ReviewRevision{
117			Version:         version,
118			SubmissionID:    s.SubmissionID,
119			Operator:        s.Operator,
120			Reason:          s.Reason,
121			Status:          s.Status,
122			ExpectedVersion: s.ExpectedVersion,
123		}
124	}
125	
126	// reviewSpec mirrors one submission document. Pointers distinguish missing
127	// fields from explicit zero values; the decoder rejects unknown fields.
128	type reviewSpec struct {
129		ChainID         *string `json:"chainId"`
130		BlockHash       *string `json:"blockHash"`
131		TxHash          *string `json:"txHash"`
132		Kind            *string `json:"kind"`
133		SubmissionID    *string `json:"submissionId"`
134		Operator        *string `json:"operator"`
135		Reason          *string `json:"reason"`
136		Status          *string `json:"status"`
137		ExpectedVersion *int    `json:"expectedVersion"`
138	}
139	
140	// reviewRule identifies one business limit every review submission must
141	// satisfy, however it was supplied (JSON spec or direct call).
142	type reviewRule int
143	
144	const (
145		ruleBlankString        reviewRule = iota // a text field is empty or all whitespace
146		ruleKnownKind                            // the conclusion kind is not sandwich/displacement
147		ruleKnownStatus                          // the status is not real/false_positive/unreviewed
148		ruleNonNegativeVersion                   // the expected version is negative
149	)
150	
151	// reviewViolation is the first business limit a submission breaks. Both
152	// submission entries render it with their own longstanding wording.
153	type reviewViolation struct {
154		rule    reviewRule
155		field   string // the submission field the rule rejected, in JSON spelling
156		value   string // the offending kind, status or text value
157		version int    // the offending expected version
158	}
159	
160	// validateReviewSubmission applies the business limits every review
161	// submission must satisfy, in the order both entries have always reported
162	// them: chain, block hash, victim tx hash, kind, submission id, operator,
163	// reason, status, then the expected version. It only judges the values —
164	// nothing is trimmed, re-cased or replaced — and returns the first
165	// violation, or nil when the submission is valid.
166	func validateReviewSubmission(sub ReviewSubmission) *reviewViolation {
167		for _, f := range []struct{ field, value string }{
168			{"chainId", sub.ChainID},
169			{"blockHash", sub.BlockHash},
170			{"txHash", sub.TxHash},
171			{"kind", sub.Kind},
172		} {
173			if strings.TrimSpace(f.value) == "" {
174				return &reviewViolation{rule: ruleBlankString, field: f.field, value: f.value}
175			}
176		}
177		if sub.Kind != SuppressSandwich && sub.Kind != SuppressDisplacement {
178			return &reviewViolation{rule: ruleKnownKind, field: "kind", value: sub.Kind}
179		}
180		for _, f := range []struct{ field, value string }{
181			{"submissionId", sub.SubmissionID},
182			{"operator", sub.Operator},
183			{"reason", sub.Reason},
184			{"status", sub.Status},
185		} {
186			if strings.TrimSpace(f.value) == "" {
187				return &reviewViolation{rule: ruleBlankString, field: f.field, value: f.value}
188			}
189		}
190		switch sub.Status {
191		case ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed:
192		default:
193			return &reviewViolation{rule: ruleKnownStatus, field: "status", value: sub.Status}
194		}
195		if sub.ExpectedVersion < 0 {
196			return &reviewViolation{rule: ruleNonNegativeVersion, field: "expectedVersion", version: sub.ExpectedVersion}
197		}
198		return nil
199	}
200	
201	// specError renders the violation with the JSON spec entry's wording.
202	func (v *reviewViolation) specError() error {
203		switch v.rule {
204		case ruleBlankString:
205			return fmt.Errorf("%s must be a non-empty string", v.field)
206		case ruleKnownKind:
207			return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, v.value)
208		case ruleKnownStatus:
209			return fmt.Errorf("invalid status %q (want %s, %s or %s)",
210				v.value, ReviewStatusReal, ReviewStatusFalsePositive, ReviewStatusUnreviewed)
211		case ruleNonNegativeVersion:
212			return fmt.Errorf("expectedVersion must be non-negative, got %d", v.version)
213		}
214		return nil
215	}
216	
217	// submitError renders the violation with the direct submission entry's
218	// wording. That entry never blank-checked kind and status separately: a
219	// blank kind reads as an unknown kind and a blank status as an invalid one,
220	// and its invalid-status message carries no candidate list.
221	func (v *reviewViolation) submitError() error {
222		switch v.rule {
223		case ruleBlankString:
224			switch v.field {
225			case "kind":
226				return fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, v.value)
227			case "status":
228				return fmt.Errorf("invalid status %q", v.value)
229			default:
230				return fmt.Errorf("%s must be a non-empty string", v.field)
231			}
232		case ruleKnownStatus:
233			return fmt.Errorf("invalid status %q", v.value)
234		default:
235			return v.specError()
236		}
237	}
238	
239	// ParseReviewSubmission validates one submission document. Identity fields
240	// and operator/reason/submissionId must be non-empty, the status must be
241	// one of real, false_positive or unreviewed, expectedVersion must be a
242	// non-negative integer, and the kind must be a known conclusion kind.
243	func ParseReviewSubmission(raw []byte) (ReviewSubmission, error) {
244		var spec reviewSpec
245		dec := json.NewDecoder(bytes.NewReader(raw))
246		dec.DisallowUnknownFields()
247		if err := dec.Decode(&spec); err != nil {
248			return ReviewSubmission{}, fmt.Errorf("invalid review spec: %w", err)
249		}
250		if dec.More() {
251			return ReviewSubmission{}, errors.New("invalid review spec: unexpected trailing data")
252		}
253		// A field the document never declares decodes as a nil pointer and
254		// reaches the shared business check as the empty value. The document's
255		// own missing-field error for that field precedes its content check, so
256		// a blank-value violation on an undeclared field is reported as the
257		// missing field instead.
258		missing := map[string]bool{}
259		value := func(field string, p *string) string {
260			if p == nil {
261				missing[field] = true
262				return ""
263			}
264			return *p
265		}
266		sub := ReviewSubmission{
267			ChainID:      value("chainId", spec.ChainID),
268			BlockHash:    value("blockHash", spec.BlockHash),
269			TxHash:       value("txHash", spec.TxHash),
270			Kind:         value("kind", spec.Kind),
271			SubmissionID: value("submissionId", spec.SubmissionID),
272			Operator:     value("operator", spec.Operator),
273			Reason:       value("reason", spec.Reason),
274			Status:       value("status", spec.Status),
275		}
276		if spec.ExpectedVersion != nil {
277			sub.ExpectedVersion = *spec.ExpectedVersion
278		}
279		if v := validateReviewSubmission(sub); v != nil {
280			if v.rule == ruleBlankString && missing[v.field] {
281				return ReviewSubmission{}, fmt.Errorf("%s is required (non-empty string)", v.field)
282			}
283			return ReviewSubmission{}, v.specError()
284		}
285		if spec.ExpectedVersion == nil {
286			return ReviewSubmission{}, errors.New("expectedVersion is required (non-negative integer)")
287		}
288		return sub, nil
289	}
290	
291	// SubmitReviewResult is the outcome of one submission attempt. Created is
292	// false when an identical submission (same ID and same field values) was
293	// retried: in that case Revision is the original revision and no new one is
294	// appended, even when the object was rejudged or withdrawn later.
295	type SubmitReviewResult struct {
296		Created   bool           `json:"created"`
297		ChainID   string         `json:"chainId"`
298		BlockHash string         `json:"blockHash"`
299		TxHash    string         `json:"txHash"`
300		Kind      string         `json:"kind"`
301		Status    string         `json:"status"`
302		Version   int            `json:"version"`
303		Revision  ReviewRevision `json:"revision"`
304	}
305	
306	// SubmitReview validates and stores one review revision. The target
307	// conclusion must exist in the archive. The first submission for an object
308	// must carry expectedVersion 0; every later one must carry the object's
309	// current version, otherwise the submission is rejected without touching
310	// stored data. Rejudgments and withdrawals append; older revisions stay.
311	// Identical retries (same archive-unique submission ID and identical
312	// fields) return the original revision. The whole update is one atomic
313	// commit under the archive lock, so concurrent submissions serialize and a
314	// stale concurrent submission can never overwrite another operator's
315	// revision.
316	func SubmitReview(dir string, sub ReviewSubmission) (SubmitReviewResult, error) {
317		if v := validateReviewSubmission(sub); v != nil {
318			return SubmitReviewResult{}, v.submitError()
319		}
320		if err := os.MkdirAll(dir, 0o755); err != nil {
321			return SubmitReviewResult{}, err
322		}
323		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
324		if err != nil {
325			return SubmitReviewResult{}, err
326		}
327		defer lock.Close()
328	
329		data, err := readArchive(dir)
330		if err != nil {
331			return SubmitReviewResult{}, err
332		}
333		if _, _, ok := findArchivedConclusion(data, sub.key()); !ok {
334			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s",
335				ErrUnknownConclusion, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind)
336		}
337	
338		// Submission IDs are unique archive-wide. An ID reuse with identical
339		// content is an idempotent retry of the original revision; it must
340		// succeed (and append nothing) even when the object has since moved on.
341		for i := range data.Reviews {
342			obj := &data.Reviews[i]
343			for _, rev := range obj.Revisions {
344				if rev.SubmissionID != sub.SubmissionID {
345					continue
346				}
347				existing := ReviewSubmission{
348					ChainID:         obj.ChainID,
349					BlockHash:       obj.BlockHash,
350					TxHash:          obj.TxHash,
351					Kind:            obj.Kind,
352					SubmissionID:    rev.SubmissionID,
353					Operator:        rev.Operator,
354					Reason:          rev.Reason,
355					Status:          rev.Status,
356					ExpectedVersion: rev.ExpectedVersion,
357				}
358				if !sub.contentEqual(existing) {
359					return SubmitReviewResult{}, fmt.Errorf("%w: %s", ErrSubmissionConflict, sub.SubmissionID)
360				}
361				return SubmitReviewResult{
362					Created:   false,
363					ChainID:   obj.ChainID,
364					BlockHash: obj.BlockHash,
365					TxHash:    obj.TxHash,
366					Kind:      obj.Kind,
367					Status:    currentReviewStatus(*obj),
368					Version:   len(obj.Revisions),
369					Revision:  rev,
370				}, nil
371			}
372		}
373	
374		idx := -1
375		for i := range data.Reviews {
376			if data.Reviews[i].key() == sub.key() {
377				idx = i
378				break
379			}
380		}
381		if idx >= 0 && data.Reviews[idx].Revisions == nil {
382			data.Reviews[idx].Revisions = []ReviewRevision{}
383		}
384		currentVersion := 0
385		if idx >= 0 {
386			currentVersion = len(data.Reviews[idx].Revisions)
387		}
388		if sub.ExpectedVersion != currentVersion {
389			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s is at version %d, submission expected %d",
390				ErrReviewConflict, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind, currentVersion, sub.ExpectedVersion)
391		}
392		rev := sub.revision(currentVersion + 1)
393		if idx < 0 {
394			data.Reviews = append(data.Reviews, ReviewObject{
395				ChainID:   sub.ChainID,
396				BlockHash: sub.BlockHash,
397				TxHash:    sub.TxHash,
398				Kind:      sub.Kind,
399				Revisions: []ReviewRevision{rev},
400			})
401		} else {
402			data.Reviews[idx].Revisions = append(data.Reviews[idx].Revisions, rev)
403		}
404		if err := writeArchiveAtomic(dir, data); err != nil {
405			return SubmitReviewResult{}, err
406		}
407		return SubmitReviewResult{
408			Created:   true,
409			ChainID:   sub.ChainID,
410			BlockHash: sub.BlockHash,
411			TxHash:    sub.TxHash,
412			Kind:      sub.Kind,
413			Status:    sub.Status,
414			Version:   currentVersion + 1,
415			Revision:  rev,
416		}, nil
417	}
418	
419	// ReviewOriginal pairs the archived conclusion with the detection version
420	// (full parameters) that produced it.
421	type ReviewOriginal struct {
422		BlockNumber int64         `json:"blockNumber"`
423		Finding     ReportFinding `json:"finding"`
424		Version     RuleVersion   `json:"version"`
425	}
426	
427	// ReviewHistory is the full revision view of one conclusion object.
428	type ReviewHistory struct {
429		ChainID   string           `json:"chainId"`
430		BlockHash string           `json:"blockHash"`
431		TxHash    string           `json:"txHash"`
432		Kind      string           `json:"kind"`
433		Status    string           `json:"status"`
434		Version   int              `json:"version"`
435		Original  *ReviewOriginal  `json:"original"`
436		Revisions []ReviewRevision `json:"revisions"`
437	}
438	
439	// currentReviewStatus returns the latest revision's status. A trailing
440	// "unreviewed" revision means an earlier judgment was withdrawn.
441	func currentReviewStatus(obj ReviewObject) string {
442		if len(obj.Revisions) == 0 {
443			return ReviewStatusUnreviewed
444		}
445		return obj.Revisions[len(obj.Revisions)-1].Status
446	}
447	
448	// ReviewHistoryQuery returns the current status and version of one
449	// conclusion object plus every revision in ascending version order. Each
450	// revision keeps its full submission content, and the response carries the
451	// original archived conclusion, the detection version parameters and the
452	// raw swap evidence. An identity without review data reports status
453	// unreviewed, version 0 and an empty list; when no archived conclusion
454	// matches the identity, original is null.
455	func ReviewHistoryQuery(dir, chainID, blockHash, txHash, kind string) (ReviewHistory, error) {
456		if strings.TrimSpace(chainID) == "" || strings.TrimSpace(blockHash) == "" ||
457			strings.TrimSpace(txHash) == "" {
458			return ReviewHistory{}, errors.New("chainId, blockHash and txHash must be non-empty strings")
459		}
460		if kind != SuppressSandwich && kind != SuppressDisplacement {
461			return ReviewHistory{}, fmt.Errorf("%w: %q (want sandwich or displacement)", ErrUnknownKind, kind)
462		}
463		out := ReviewHistory{
464			ChainID:   chainID,
465			BlockHash: blockHash,
466			TxHash:    txHash,
467			Kind:      kind,
468			Status:    ReviewStatusUnreviewed,
469			Version:   0,
470			Original:  nil,
471			Revisions: []ReviewRevision{},
472		}
473		key := conclusionKey{chainID, blockHash, txHash, kind}
474		if _, serr := os.Stat(dir); serr != nil {
475			if errors.Is(serr, os.ErrNotExist) {
476				return out, nil
477			}
478			return ReviewHistory{}, serr
479		}
480		lock, err := lockArchive(dir, syscall.LOCK_SH)
481		if err != nil {
482			return ReviewHistory{}, err
483		}
484		defer lock.Close()
485	
486		data, err := readArchive(dir)
487		if err != nil {
488			return ReviewHistory{}, err
489		}
490		if rec, f, ok := findArchivedConclusion(data, key); ok {
491			out.Original = &ReviewOriginal{
492				BlockNumber: rec.BlockNumber,
493				Finding:     f,
494				Version:     rec.ruleVersion(),
495			}
496		}
497		for i := range data.Reviews {
498			obj := data.Reviews[i]
499			if obj.key() != key {
500				continue
501			}
502			out.Version = len(obj.Revisions)
503			out.Status = currentReviewStatus(obj)
504			out.Revisions = append([]ReviewRevision(nil), obj.Revisions...)
505			break
506		}
507		if out.Revisions == nil {
508			out.Revisions = []ReviewRevision{}
509		}
510		return out, nil
511	}
512	
513	// findArchivedConclusion locates the record and the finding for an identity.
514	func findArchivedConclusion(data archiveData, key conclusionKey) (record, ReportFinding, bool) {
515		for _, rec := range data.Records {
516			if rec.ChainID != key.chainID || rec.BlockHash != key.blockHash {
517				continue
518			}
519			for _, f := range rec.Findings {
520				if f.TxHash == key.txHash && f.Kind == key.kind {
521					return rec, f, true
522				}
523			}
524		}
525		return record{}, ReportFinding{}, false
526	}
527	
528	// ReviewConclusion pairs a conclusion with the rule version whose
529	// parameters produced it. The finding itself carries the raw swap evidence.
530	type ReviewConclusion struct {
531		Finding ReportFinding `json:"finding"`
532		Version RuleVersion   `json:"version"`
533	}
534	
535	// ReviewDetail is one evaluated conclusion with its bucket, the revision
536	// that decided it (null when there is no valid review), the original and
537	// candidate conclusions (either side may be null), their rule parameters
538	// and their swap evidence.
539	type ReviewDetail struct {
540		ChainID         string            `json:"chainId"`
541		BlockHash       string            `json:"blockHash"`
542		BlockNumber     int64             `json:"blockNumber"`
543		TxHash          string            `json:"txHash"`
544		Kind            string            `json:"kind"`
545		Bucket          string            `json:"bucket"`
546		AppliedRevision *ReviewRevision   `json:"appliedRevision"`
547		Original        *ReviewConclusion `json:"original"`
548		Candidate       *ReviewConclusion `json:"candidate"`
549	}
550	
551	// ReviewEvaluation is the false-positive analysis over one inclusive height
552	// range, judged consistently against one archive snapshot and its latest
553	// review state.
554	type ReviewEvaluation struct {
555		ChainID     string         `json:"chainId"`
556		StartHeight uint64         `json:"startHeight"`
557		EndHeight   uint64         `json:"endHeight"`
558		Version     RuleVersion    `json:"version"`
559		Retained    int            `json:"retained"`
560		Missed      int            `json:"missed"`
561		StillHit    int            `json:"stillHit"`
562		Eliminated  int            `json:"eliminated"`
563		Pending     int            `json:"pending"`
564		Details     []ReviewDetail `json:"details"`
565	}
566	
567	// sortReviewDetails orders by height, block hash, tx hash and kind.
568	func sortReviewDetails(details []ReviewDetail) {
569		sort.Slice(details, func(i, j int) bool {
570			a, b := details[i], details[j]
571			if a.BlockNumber != b.BlockNumber {
572				return a.BlockNumber < b.BlockNumber
573			}
574			if a.BlockHash != b.BlockHash {
575				return a.BlockHash < b.BlockHash
576			}
577			if a.TxHash != b.TxHash {
578				return a.TxHash < b.TxHash
579			}
580			return a.Kind < b.Kind
581		})
582	}
583	
584	// EvaluateReviews re-judges every archived block on chainID in the inclusive
585	// range [startHeight, endHeight] under the given registered rule version and
586	// compares the candidate conclusions against archived originals, using only
587	// archived evidence and the latest review state. Only original conclusions
588	// marked real or false positive feed the four counts: real risks split into
589	// retained (same tx and same kind still hits; severity changes do not
590	// matter) and missed; false positives split into still hit and eliminated.
591	// A candidate hit on the same tx and kind without a valid (non-withdrawn)
592	// review counts as pending, as does the new kind when the candidate changes
593	// a tx's conclusion type; withdrawn objects behave as unreviewed. The call
594	// is read-only: reports, the enabled version, reviews and alert records are
595	// never modified. An empty range yields zero counts and an empty list.
596	func EvaluateReviews(dir, chainID string, startHeight, endHeight uint64, versionID string) (ReviewEvaluation, error) {
597		if strings.TrimSpace(chainID) == "" {
598			return ReviewEvaluation{}, errors.New("chainId must be a non-empty string")
599		}
600		if strings.TrimSpace(versionID) == "" {
601			return ReviewEvaluation{}, errors.New("version id must not be empty")
602		}
603		if startHeight > endHeight {
604			return ReviewEvaluation{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
605		}
606		result := ReviewEvaluation{
607			ChainID:     chainID,
608			StartHeight: startHeight,
609			EndHeight:   endHeight,
610			Details:     []ReviewDetail{},
611		}
612		if _, serr := os.Stat(dir); serr != nil {
613			if errors.Is(serr, os.ErrNotExist) {
614				// An absent archive has only the built-in version registered, so
615				// any other id is an unknown version even though the range would
616				// match no blocks.
617				if versionID != BuiltinVersionID {
618					return ReviewEvaluation{}, fmt.Errorf("%w: %s", ErrUnknownVersion, versionID)
619				}
620				result.Version = BuiltinVersion()
621				return result, nil
622			}
623			return ReviewEvaluation{}, serr
624		}
625		// One shared lock for the whole evaluation: the archive snapshot and the
626		// latest review state stay consistent across every block.
627		lock, err := lockArchive(dir, syscall.LOCK_SH)
628		if err != nil {
629			return ReviewEvaluation{}, err
630		}
631		defer lock.Close()
632	
633		data, err := readArchive(dir)
634		if err != nil {
635			return ReviewEvaluation{}, err
636		}
637		candidate, err := findVersion(data, versionID)
638		if err != nil {
639			return ReviewEvaluation{}, err
640		}
641		result.Version = candidate
642	
643		reviews := make(map[conclusionKey]*ReviewObject, len(data.Reviews))
644		for i := range data.Reviews {
645			reviews[data.Reviews[i].key()] = &data.Reviews[i]
646		}
647	
648		details := []ReviewDetail{}
649		for _, rec := range data.Records {
650			if rec.ChainID != chainID {
651				continue
652			}
653			height := uint64(rec.BlockNumber)
654			if height < startHeight || height > endHeight {
655				continue
656			}
657			originalVersion := rec.ruleVersion()
658			candidateFindings := DetectBlockWithRules(rec.Swaps, candidate.Rules)
659			candByKey := make(map[conclusionKey]ReportFinding, len(candidateFindings))
660			candByTx := make(map[string]ReportFinding, len(candidateFindings))
661			for _, cf := range candidateFindings {
662				candByKey[conclusionKey{rec.ChainID, rec.BlockHash, cf.TxHash, cf.Kind}] = cf
663				candByTx[cf.TxHash] = cf
664			}
665	
666			// Original conclusions: only reviewed (real/false-positive) ones
667			// enter the four counts; same-kind candidate hits without a valid
668			// review are pending; originals that simply vanished without review
669			// are not counted anywhere.
670			for _, of := range rec.Findings {
671				key := conclusionKey{rec.ChainID, rec.BlockHash, of.TxHash, of.Kind}
672				obj := reviews[key]
673				original := &ReviewConclusion{Finding: of, Version: originalVersion}
674				if obj == nil || currentReviewStatus(*obj) == ReviewStatusUnreviewed {
675					if cf, ok := candByKey[key]; ok {
676						details = append(details, ReviewDetail{
677							ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
678							TxHash: of.TxHash, Kind: of.Kind, Bucket: BucketPending,
679							Original: original, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
680						})
681					}
682					continue
683				}
684				rev := obj.Revisions[len(obj.Revisions)-1]
685				detail := ReviewDetail{
686					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
687					TxHash: of.TxHash, Kind: of.Kind, AppliedRevision: &rev, Original: original,
688				}
689				cf, hit := candByKey[key]
690				if hit {
691					detail.Candidate = &ReviewConclusion{Finding: cf, Version: candidate}
692				}
693				switch rev.Status {
694				case ReviewStatusReal:
695					if hit {
696						detail.Bucket = BucketRetained
697					} else {
698						detail.Bucket = BucketMissed
699					}
700				case ReviewStatusFalsePositive:
701					if hit {
702						detail.Bucket = BucketStillHit
703					} else {
704						detail.Bucket = BucketEliminated
705					}
706				}
707				details = append(details, detail)
708			}
709	
710			// Candidate conclusions whose (tx, kind) matches no original: when
711			// the same tx carried a different original kind this is the "new
712			// type" side of a type change; either way it is unreviewed and
713			// pending.
714			for _, cf := range candidateFindings {
715				if _, sameKind := findOriginalFinding(rec, cf.TxHash, cf.Kind); sameKind {
716					continue
717				}
718				details = append(details, ReviewDetail{
719					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
720					TxHash: cf.TxHash, Kind: cf.Kind, Bucket: BucketPending,
721					Original: nil, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
722				})
723			}
724		}
725	
726		for _, d := range details {
727			switch d.Bucket {
728			case BucketRetained:
729				result.Retained++
730			case BucketMissed:
731				result.Missed++
732			case BucketStillHit:
733				result.StillHit++
734			case BucketEliminated:
735				result.Eliminated++
736			case BucketPending:
737				result.Pending++
738			}
739		}
740		sortReviewDetails(details)
741		result.Details = details
742		return result, nil
743	}
744	
745	func findOriginalFinding(rec record, txHash, kind string) (ReportFinding, bool) {
746		for _, f := range rec.Findings {
747			if f.TxHash == txHash && f.Kind == kind {
748				return f, true
749			}
750		}
751		return ReportFinding{}, false
752	}
753

