	var err error
	if versionID != "" {
		reports, err = mevwatch.ReplayFileWithVersion(rest[0], rest[1], versionID)
	} else {
		reports, err = mevwatch.ReplayFile(rest[0], rest[1])
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "replay: %v\n", err)
		os.Exit(1)
	}
	for _, report := range reports {
		writeJSON(report)
	}
}

func runRules(args []string) {
