550	// rewriteStoredVersion rewrites the stored archive document of the
551	// registered version id through mutate, simulating an archive whose
552	// registered version no longer satisfies the registration rules even
553	// though the file is still valid JSON.
554	func rewriteStoredVersion(t *testing.T, dir, id string, mutate func(ver map[string]any)) {
555		t.Helper()
556		path := filepath.Join(dir, archiveFileName)
557		raw, err := os.ReadFile(path)
558		if err != nil {
559			t.Fatal(err)
560		}
561		var doc map[string]any
562		if err := json.Unmarshal(raw, &doc); err != nil {
563			t.Fatal(err)
564		}
565		versions, ok := doc["versions"].([]any)
566		if !ok {
567			t.Fatalf("no versions array in archive: %s", raw)
568		}
569		found := false
570		for _, entry := range versions {
571			ver, ok := entry.(map[string]any)
572			if !ok || ver["id"] != id {
573				continue
574			}
575			mutate(ver)
576			found = true
577		}
578		if !found {
579			t.Fatalf("version %s not stored in archive", id)
580		}
581		out, err := json.MarshalIndent(doc, "", "  ")
582		if err != nil {
583			t.Fatal(err)
584		}
585		if err := os.WriteFile(path, out, 0o644); err != nil {
586			t.Fatal(err)
587		}
588	}
