1	package main
2	
3	// End-to-end regression coverage for the `compare` command entry point.
4	// The test binary re-executes itself (see TestMain) and runs the real
5	// main(), so these tests exercise argument parsing, exit status, stderr
6	// failure wording and the exact stdout JSON exactly as a user does.
7	// Everything runs offline against archive directories under t.TempDir;
8	// the original block input file is deleted before the CLI is invoked,
9	// proving comparison reads archived swap records only.
10	
11	import (
12		"bytes"
13		"encoding/json"
14		"os"
15		"path/filepath"
16		"reflect"
17		"strings"
18		"testing"
19	
20		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
21	)
22	
23	const cliHelperEnv = "MEVWATCH_TEST_HELPER"
24	
25	// cliResult is the captured outcome of one forked CLI invocation.
26	type cliResult struct {
27		stdout   string
28		stderr   string
29		exitCode int
30	}
31	
32	func TestMain(m *testing.M) {
33		if os.Getenv(cliHelperEnv) == "1" {
34			main()
35			return
36		}
37		os.Exit(m.Run())
38	}
39	
40	// runCLI executes the real command entry with the given arguments in a
41	// forked copy of the test binary.
42	func runCLI(t *testing.T, args ...string) cliResult {
43		t.Helper()
44		cmd := execCommand(args...)
45		var stdout, stderr bytes.Buffer
46		cmd.Stdout = &stdout
47		cmd.Stderr = &stderr
48		err := cmd.Run()
49		code := 0
50		if err != nil {
51			code = exitCode(t, err)
52		}
53		return cliResult{stdout: stdout.String(), stderr: stderr.String(), exitCode: code}
54	}
55	
56	type cliSwap = map[string]any
57	
58	func cliSwapRecord(tx, pool, trader string, gas int64, index int) cliSwap {
59		return map[string]any{
60			"TxHash": tx, "Pool": pool, "Trader": trader,
61			"In": 1, "Out": 1, "GasPrice": gas, "Index": index,
62		}
63	}
64	
65	func cliBlockLine(chain, hash string, number int64, swaps ...cliSwap) string {
66		raw, err := json.Marshal(map[string]any{
67			"chainId": chain, "blockHash": hash, "blockNumber": number, "swaps": swaps,
68		})
69		if err != nil {
70			panic(err)
71		}
72		return string(raw)
73	}
74	
75	// setupCLIArchive builds an archive exercising every diff shape and
76	// deletes the source input file before returning:
77	//
78	//	p1 0xa1 sandwich sev4 (archived under archA) -> displacement sev4
79	//	   under candC (sandwich disabled): kind change;
80	//	p2 0xb1 displacement sev1 multiplier 3 -> sev4 multiplier 2:
81	//	   severity change;
82	//	p3 0xd1 nothing under archA (21 <= 30) -> displacement sev4 under
83	//	   candC (21 > 20): added;
84	//	p4 0xe1 sandwich sev4 under archA, nothing under candC (16 <= 20):
85	//	   removed.
86	func setupCLIArchive(t *testing.T) (dir string) {
87		t.Helper()
88		dir = t.TempDir()
89		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
90		lines := []string{
91			cliBlockLine("1", "0xblk", 42,
92				cliSwapRecord("0xaf", "p1", "bot", 90, 0),
93				cliSwapRecord("0xa1", "p1", "user", 10, 1),
94				cliSwapRecord("0xab", "p1", "bot", 80, 2),
95				cliSwapRecord("0xbf", "p2", "w", 40, 3),
96				cliSwapRecord("0xb1", "p2", "u", 10, 4),
97				cliSwapRecord("0xbz", "p2", "z", 10, 5),
98				cliSwapRecord("0xdf", "p3", "w", 21, 6),
99				cliSwapRecord("0xd1", "p3", "u", 10, 7),
100				cliSwapRecord("0xef", "p4", "bot", 16, 8),
101				cliSwapRecord("0xe1", "p4", "user", 10, 9),
102				cliSwapRecord("0xeb", "p4", "bot", 12, 10),
103			),
104			// Same height, different hash: must never mix into 0xblk.
105			cliBlockLine("1", "0xother", 42,
106				cliSwapRecord("0zz0", "pz", "tz", 900, 0),
107				cliSwapRecord("0zz1", "pz", "tz2", 901, 1),
108			),
109			// Same height and hash on a different chain: also must not mix.
110			cliBlockLine("2", "0xblk", 42,
111				cliSwapRecord("0qq0", "pq", "tq", 700, 0),
112				cliSwapRecord("0qq1", "pq", "tq2", 701, 1),
113			),
114		}
115		if err := os.WriteFile(inputPath, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
116			t.Fatal(err)
117		}
118		const (
119			archA = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
120			liveB = `{"id":"liveB","rules":{"sandwich":{"enabled":true,"severity":5},"displacement":{"enabled":true,"severity":5,"multiplier":4}}}`
121			candC = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
122		)
123		for _, spec := range []string{archA, liveB, candC} {
124			if _, _, err := mevwatch.RegisterVersion(dir, []byte(spec)); err != nil {
125				t.Fatalf("RegisterVersion: %v", err)
126			}
127		}
128		reports, err := mevwatch.ReplayFileWithVersion(inputPath, dir, "archA")
129		if err != nil {
130			t.Fatalf("ReplayFileWithVersion: %v", err)
131		}
132		if len(reports) != 3 {
133			t.Fatalf("got %d reports, want 3", len(reports))
134		}
135		if _, err := mevwatch.EnableVersion(dir, "liveB"); err != nil {
136			t.Fatalf("EnableVersion: %v", err)
137		}
138		if err := os.Remove(inputPath); err != nil {
139			t.Fatal(err)
140		}
141		return dir
142	}
143	
144	func parseCompareJSON(t *testing.T, raw string) mevwatch.CompareResult {
145		t.Helper()
146		var result mevwatch.CompareResult
147		if err := json.Unmarshal([]byte(raw), &result); err != nil {
148			t.Fatalf("stdout is not valid JSON: %v\n%s", err, raw)
149		}
150		return result
151	}
152	
153	func TestCLICompareSuccessJSON(t *testing.T) {
154		dir := setupCLIArchive(t) // input file already deleted
155	
156		res := runCLI(t, "compare", dir, "1", "0xblk", "candC")
157		if res.exitCode != 0 {
158			t.Fatalf("exit=%d stderr=%q", res.exitCode, res.stderr)
159		}
160		if strings.TrimSpace(res.stderr) != "" {
161			t.Fatalf("unexpected stderr: %q", res.stderr)
162		}
163		// Exactly one JSON object on stdout, no extra text.
164		if !strings.HasSuffix(res.stdout, "}\n") || strings.Count(strings.TrimSpace(res.stdout), "{") < 1 {
165			t.Fatalf("stdout shape wrong: %q", res.stdout)
166		}
167		result := parseCompareJSON(t, res.stdout)
168	
169		// Identity corresponds to the selected block only.
170		if result.ChainID != "1" || result.BlockHash != "0xblk" || result.BlockNumber != 42 {
171			t.Fatalf("block identity wrong: %s/%s @%d", result.ChainID, result.BlockHash, result.BlockNumber)
172		}
173	
174		// Historical side keeps the archive-time version archA; the candidate
175		// side uses candC, not the currently enabled liveB. Each side carries
176		// its complete parameters.
177		if result.OriginalVersion.ID != "archA" ||
178			result.OriginalVersion.Rules.Sandwich.Severity != 4 ||
179			result.OriginalVersion.Rules.Displacement.Multiplier != 3 ||
180			result.OriginalVersion.Rules.Displacement.Severity != 1 {
181			t.Fatalf("original side must keep archived version params: %+v", result.OriginalVersion)
182		}
183		if result.ComparedVersion.ID != "candC" ||
184			result.ComparedVersion.Rules.Sandwich.Enabled ||
185			result.ComparedVersion.Rules.Displacement.Severity != 4 ||
186			result.ComparedVersion.Rules.Displacement.Multiplier != 2 {
187			t.Fatalf("candidate side must use the named version params: %+v", result.ComparedVersion)
188		}
189	
190		// Full conclusions: severity desc, hash asc. 0xa1/0xe1 are sandwich
191		// sev4, 0xb1 displacement sev1.
192		if len(result.OriginalFindings) != 3 {
193			t.Fatalf("original findings = %+v", result.OriginalFindings)
194		}
195		wantOrig := []struct {
196			tx   string
197			kind string
198			sev  int
199		}{
200			{"0xa1", "sandwich", 4},
201			{"0xe1", "sandwich", 4},
202			{"0xb1", "displacement", 1},
203		}
204		for i, w := range wantOrig {
205			got := result.OriginalFindings[i]
206			if got.TxHash != w.tx || got.Kind != w.kind || got.Severity != w.sev {
207				t.Fatalf("original[%d] = %+v, want %+v", i, got, w)
208			}
209		}
210		// Candidate side: three displacement sev4, hash asc.
211		if len(result.ComparedFindings) != 3 {
212			t.Fatalf("compared findings = %+v", result.ComparedFindings)
213		}
214		wantComp := []string{"0xa1", "0xb1", "0xd1"}
215		for i, tx := range wantComp {
216			got := result.ComparedFindings[i]
217			if got.TxHash != tx || got.Kind != "displacement" || got.Severity != 4 {
218				t.Fatalf("compared[%d] = %+v, want %s displacement 4", i, got, tx)
219			}
220		}
221	
222		// Per-victim diff: added, removed, and two changes hash asc.
223		if len(result.Added) != 1 || result.Added[0].TxHash != "0xd1" {
224			t.Fatalf("added = %+v", result.Added)
225		}
226		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xe1" {
227			t.Fatalf("removed = %+v", result.Removed)
228		}
229		if len(result.Changed) != 2 ||
230			result.Changed[0].TxHash != "0xa1" || result.Changed[1].TxHash != "0xb1" {
231			t.Fatalf("changed = %+v", result.Changed)
232		}
233		// Sandwich -> displacement keeps BOTH conclusions in one change entry.
234		kindChange := result.Changed[0]
235		if kindChange.Original.Kind != "sandwich" || kindChange.Original.Severity != 4 ||
236			len(kindChange.Original.Evidence) != 3 {
237			t.Fatalf("kind change original side wrong: %+v", kindChange.Original)
238		}
239		if kindChange.Compared.Kind != "displacement" || kindChange.Compared.Severity != 4 ||
240			len(kindChange.Compared.Evidence) != 2 {
241			t.Fatalf("kind change compared side wrong: %+v", kindChange.Compared)
242		}
243		// Severity-only change keeps both sides with the same kind.
244		sevChange := result.Changed[1]
245		if sevChange.Original.Kind != "displacement" || sevChange.Original.Severity != 1 ||
246			sevChange.Compared.Kind != "displacement" || sevChange.Compared.Severity != 4 {
247			t.Fatalf("severity change wrong: %+v", sevChange)
248		}
249	
250		// Full archived swap records survive (11 records for this block), and
251		// conclusion evidence keeps raw tx/pool/trader/amount/gas/index.
252		if len(result.Swaps) != 11 {
253			t.Fatalf("full swap records missing: %+v", result.Swaps)
254		}
255		if result.Swaps[0] != (mevwatch.Swap{TxHash: "0xaf", Pool: "p1", Trader: "bot", In: 1, Out: 1, GasPrice: 90, Index: 0}) {
256			t.Fatalf("raw swap fields damaged: %+v", result.Swaps[0])
257		}
258		front := result.Changed[0].Original.Evidence[0]
259		if front.TxHash != "0xaf" || front.Pool != "p1" || front.Trader != "bot" ||
260			front.In != 1 || front.Out != 1 || front.GasPrice != 90 || front.Index != 0 {
261			t.Fatalf("conclusion evidence damaged: %+v", front)
262		}
263	
264		// Output is deterministic across repeated offline invocations.
265		again := runCLI(t, "compare", dir, "1", "0xblk", "candC")
266		if again.exitCode != 0 {
267			t.Fatalf("second run failed: %d %q", again.exitCode, again.stderr)
268		}
269		if again.stdout != res.stdout {
270			t.Fatalf("compare output is not deterministic:\n%s\n%s", res.stdout, again.stdout)
271		}
272	}
273	
274	func TestCLICompareScoping(t *testing.T) {
275		dir := setupCLIArchive(t)
276	
277		sameHeightOther := runCLI(t, "compare", dir, "1", "0xother", "candC")
278		if sameHeightOther.exitCode != 0 {
279			t.Fatalf("other block compare failed: %q", sameHeightOther.stderr)
280		}
281		r := parseCompareJSON(t, sameHeightOther.stdout)
282		if r.BlockHash != "0xother" || r.BlockNumber != 42 || len(r.Swaps) != 2 ||
283			r.Swaps[0].TxHash != "0zz0" {
284			t.Fatalf("same-height other block mixed records in: %+v", r)
285		}
286	
287		otherChain := runCLI(t, "compare", dir, "2", "0xblk", "candC")
288		if otherChain.exitCode != 0 {
289			t.Fatalf("other chain compare failed: %q", otherChain.stderr)
290		}
291		r = parseCompareJSON(t, otherChain.stdout)
292		if r.ChainID != "2" || r.BlockHash != "0xblk" || len(r.Swaps) != 2 ||
293			r.Swaps[0].TxHash != "0qq0" {
294			t.Fatalf("other chain records mixed in: %+v", r)
295		}
296		for _, f := range append(append([]mevwatch.ReportFinding{}, r.OriginalFindings...), r.ComparedFindings...) {
297			if strings.HasPrefix(f.TxHash, "0xa") || f.TxHash == "0xb1" {
298				t.Fatalf("chain-1 conclusion leaked into chain-2 result: %+v", f)
299			}
300		}
301	}
302	
303	func TestCLICompareFailures(t *testing.T) {
304		dir := setupCLIArchive(t)
305	
306		cases := []struct {
307			name     string
308			args     []string
309			wantCode int
310			wantErr  string
311		}{
312			{"unknown block", []string{"compare", dir, "1", "0xghost", "candC"}, 1, "unknown block"},
313			{"unknown chain", []string{"compare", dir, "9", "0xblk", "candC"}, 1, "unknown block"},
314			{"unregistered version", []string{"compare", dir, "1", "0xblk", "nope"}, 1, "unknown version: nope"},
315			{"missing archive dir", []string{"compare", filepath.Join(dir, "missing"), "1", "0xblk", "candC"}, 1, "unknown block"},
316			{"too few args", []string{"compare", dir, "1", "0xblk"}, 2, "usage: mevwatch compare"},
317			{"too many args", []string{"compare", dir, "1", "0xblk", "candC", "extra"}, 2, "usage: mevwatch compare"},
318		}
319		for _, tc := range cases {
320			t.Run(tc.name, func(t *testing.T) {
321				res := runCLI(t, tc.args...)
322				if res.exitCode != tc.wantCode {
323					t.Fatalf("exit = %d, want %d; stdout=%q stderr=%q",
324						res.exitCode, tc.wantCode, res.stdout, res.stderr)
325				}
326				if res.stdout != "" {
327					t.Fatalf("failure must print no success JSON, got %q", res.stdout)
328				}
329				if !strings.Contains(res.stderr, tc.wantErr) {
330					t.Fatalf("stderr = %q, want substring %q", res.stderr, tc.wantErr)
331				}
332			})
333		}
334	}
335	
336	func TestCLICompareEmptyBothSides(t *testing.T) {
337		dir := t.TempDir()
338		const (
339			archA = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
340			candC = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
341		)
342		for _, spec := range []string{archA, candC} {
343			if _, _, err := mevwatch.RegisterVersion(dir, []byte(spec)); err != nil {
344				t.Fatal(err)
345			}
346		}
347		inputPath := filepath.Join(t.TempDir(), "empty.jsonl")
348		if err := os.WriteFile(inputPath, []byte(cliBlockLine("1", "0none", 1,
349			cliSwapRecord("0g0", "p", "w", 15, 0),
350			cliSwapRecord("0g1", "p", "u", 10, 1),
351		)+"\n"), 0o644); err != nil {
352			t.Fatal(err)
353		}
354		if _, err := mevwatch.ReplayFileWithVersion(inputPath, dir, "archA"); err != nil {
355			t.Fatal(err)
356		}
357		if err := os.Remove(inputPath); err != nil {
358			t.Fatal(err)
359		}
360	
361		res := runCLI(t, "compare", dir, "1", "0none", "candC")
362		if res.exitCode != 0 {
363			t.Fatalf("exit=%d stderr=%q", res.exitCode, res.stderr)
364		}
365		result := parseCompareJSON(t, res.stdout)
366		if len(result.OriginalFindings) != 0 || len(result.ComparedFindings) != 0 ||
367			len(result.Added) != 0 || len(result.Removed) != 0 || len(result.Changed) != 0 {
368			t.Fatalf("both sides empty must yield empty lists: %+v", result)
369		}
370		if len(result.Swaps) != 2 {
371			t.Fatalf("full swap records must remain: %+v", result.Swaps)
372		}
373		// The wire format must be [], never null.
374		for _, key := range []string{`"originalFindings":[]`, `"comparedFindings":[]`, `"added":[]`, `"removed":[]`, `"changed":[]`} {
375			if !strings.Contains(res.stdout, key) {
376				t.Fatalf("stdout missing %s:\n%s", key, res.stdout)
377			}
378		}
