381	func TestCLICompareLegacyArchiveBuiltin(t *testing.T) {
382		dir := t.TempDir()
383		// Pre-version archive (no version field on the record).
384		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
385			`"swaps":[` +
386			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
387			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
388			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
389			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
390			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
391			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
392			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
393		if err := os.WriteFile(filepath.Join(dir, "archive.json"), []byte(legacy), 0o644); err != nil {
394			t.Fatal(err)
395		}
396		const candC = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
397		if _, _, err := mevwatch.RegisterVersion(dir, []byte(candC)); err != nil {
398			t.Fatal(err)
399		}
400		res := runCLI(t, "compare", dir, "1", "0old", "candC")
401		if res.exitCode != 0 {
402			t.Fatalf("exit=%d stderr=%q", res.exitCode, res.stderr)
403		}
404		result := parseCompareJSON(t, res.stdout)
405		if result.OriginalVersion.ID != "builtin" ||
406			result.OriginalVersion.Rules.Sandwich.Severity != 3 ||
407			result.OriginalVersion.Rules.Displacement.Multiplier != 2 {
408			t.Fatalf("legacy record must be explained as builtin: %+v", result.OriginalVersion)
409		}
410		if len(result.OriginalFindings) != 1 || result.OriginalFindings[0].Kind != "sandwich" {
411			t.Fatalf("legacy conclusions damaged: %+v", result.OriginalFindings)
412		}
413		if len(result.ComparedFindings) != 1 || result.ComparedFindings[0].Kind != "displacement" ||
414			result.ComparedFindings[0].Severity != 4 {
415			t.Fatalf("candidate re-judgment wrong: %+v", result.ComparedFindings)
416		}
