419	func TestCLICompareIsReadOnly(t *testing.T) {
420		dir := setupCLIArchive(t)
421		archivePath := filepath.Join(dir, "archive.json")
422		before, err := os.ReadFile(archivePath)
423		if err != nil {
424			t.Fatal(err)
425		}
426	
427		// Successful comparisons against every block...
428		for _, args := range [][]string{
429			{"compare", dir, "1", "0xblk", "candC"},
430			{"compare", dir, "1", "0xblk", "builtin"},
431			{"compare", dir, "1", "0xother", "candC"},
432			{"compare", dir, "2", "0xblk", "candC"},
433			// ...and every failure shape leave the archive byte-identical.
434			{"compare", dir, "1", "0xghost", "candC"},
435			{"compare", dir, "1", "0xblk", "ghost"},
436		} {
437			runCLI(t, args...)
438		}
439	
440		after, err := os.ReadFile(archivePath)
441		if err != nil {
442			t.Fatal(err)
443		}
444		if !reflect.DeepEqual(before, after) {
445			t.Fatalf("compare modified the archive file")
446		}
447	
448		// The archived report and the enabled version are both unchanged.
449		report, err := mevwatch.Query(dir, "1", "0xblk")
450		if err != nil {
451			t.Fatal(err)
452		}
453		if report.Version.ID != "archA" || len(report.Findings) != 3 {
454			t.Fatalf("archived report changed: %+v", report)
455		}
456		_, enabled, err := mevwatch.ListVersions(dir)
457		if err != nil {
458			t.Fatal(err)
