494	func TestCLICompareCorruptVersion(t *testing.T) {
495		dir := setupCLIArchive(t)
496		// The stored candC document loses its displacement multiplier: valid
497		// JSON, but no longer a complete rule declaration.
498		corruptStoredVersion(t, dir, "candC", func(ver map[string]any) {
499			delete(ver["rules"].(map[string]any)["displacement"].(map[string]any), "multiplier")
500		})
501	
502		res := runCLI(t, "compare", dir, "1", "0xblk", "candC")
503		if res.exitCode != 1 {
504			t.Fatalf("exit = %d, want 1; stdout=%q stderr=%q", res.exitCode, res.stdout, res.stderr)
505		}
506		if res.stdout != "" {
507			t.Fatalf("corrupt version must print no success JSON, got %q", res.stdout)
508		}
509		for _, want := range []string{"corrupt", "candC", "multiplier"} {
510			if !strings.Contains(res.stderr, want) {
511				t.Fatalf("stderr = %q, want substring %q", res.stderr, want)
512			}
513		}
514	
515		// An unregistered version stays a plain unknown-version failure.
516		res = runCLI(t, "compare", dir, "1", "0xblk", "nope")
517		if res.exitCode != 1 || !strings.Contains(res.stderr, "unknown version: nope") ||
518			strings.Contains(res.stderr, "corrupt") {
519			t.Fatalf("unknown version failure changed shape: exit=%d stderr=%q", res.exitCode, res.stderr)
520		}
521	
522		// The corrupt sibling does not contaminate intact versions.
523		res = runCLI(t, "compare", dir, "1", "0xblk", "builtin")
524		if res.exitCode != 0 {
525			t.Fatalf("compare under builtin failed: %d %q", res.exitCode, res.stderr)
526		}
